import{_ as l,l as o,o as e,c as n,v as t,p as s,x as i,d as p,i as h,S as d}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"标准单元与轨道高度","description":"","frontmatter":{"title":"标准单元与轨道高度","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/standard-cell-track-height.md","filePath":"litho/standard-cell-track-height.md","lastUpdated":1789023840000}'),c={name:"litho/standard-cell-track-height.md"};function T(m,a,_,f,A,E){const r=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="标准单元与轨道高度" tabindex="-1">标准单元与轨道高度 <a class="header-anchor" href="#标准单元与轨道高度" aria-label="Permalink to &quot;标准单元与轨道高度&quot;">​</a></h1><div class="epigraph"><p>轨道高度是标准单元的纵向节拍：它把金属节距、电源轨和可印取向收成一个整数，密度与可布线性在此对赌。</p><footer>—— 对照 imec DTCO 对 track height、FinFlex 与布线网格的公开论述</footer></div><p><a href="/litho/min-area-tip-to-tip">上一课</a>把 tip 与面积写成独立条款。缺口是单元：逻辑库用几条金属轨高，直接决定有多少 tip、多少 via、电源是否挤在不可印的缝里。<a href="/litho/dtco-patterning">DTCO</a> 已点名轨道；本课钉图形化侧如何选轨高。缩放助推器（接触上栅、埋入电源等）留给[下一课](/litho/scaling-boosters）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>标准单元高度常以金属 2（或中间层）轨道数计：6T、7.5T、5T 一类。轨少则密度高，但电源、信号、扩散接触争同一套 tip-to-tip 与 via 覆盖预算；轨多则好布、好印，面积涨。Fin/nanosheet 的器件宽度分档（FinFlex 一类）让同一轨高下 drive 可变，但布线通道数仍被轨高锁死。</p><p>缺口是<strong>轨高作为光刻约束的整数</strong>，不是重讲标准单元电路。把轨高当纯设计风格，会忽略：单向金属加切线、EUV 单次对二维 jog 的容忍、以及电源轨 CD 对电迁徙的可靠性规则。</p><h3 id="半轨与奇数轨" tabindex="-1">半轨与奇数轨 <a class="header-anchor" href="#半轨与奇数轨" aria-label="Permalink to &quot;半轨与奇数轨&quot;">​</a></h3><p>非整数轨（7.5T）来自器件与金属网格不对齐或电源轨加倍。半轨让布线灵活，却制造更多不规则 tip 与着色困难。LFD 必须对整库、而不是只对 inverter 跑前向。奇数轨对镜像单元和电源网格的周期性不友好，填充与刻蚀密度也会破周期。</p><p><span class="marginnote">单元库 freeze 等于冻结该层最密、最二维的 clips。OPC 模型的保持集应含库，而不是只含逻辑随机布线。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>候选轨高 × 金属节距 × 分解选项 → 代表单元（逆变器、触发器、多指）跑 SMO/OPC/PV 与 via 覆盖。看：热点数、切线需求、电源轨窗口、可布线性（销钉是否够）。与 <a href="/litho/cpp-mmp">CPP/MMP</a> 后课（路线图门）的关系：本课只问图形化可实现；晶体管密度数字留给节点命名课序。High-NA 半场是否逼大核改芯粒，是 DTCO 面积，本课只要求轨高评估包含拼接假设。</p><p>触发器和多位加法器比 inverter 更吃 tip 与 via 色。轨高评估集必须含这些，否则 6T 库在 inverter 上绿灯、在时序单元上红。imec 公开 DTCO 叙述正是用代表单元族，而不是单一标准单元。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>轨高 \\(H = N \\times\\) 金属节距（加电源特例）。\\(N\\) 下降，信号轨变少，布线器更常制造 tip 对撞和错误 via 颜色。光学上，密且重复的单元是周期结构，RCWA/紧凑核都较稳；一旦半轨破坏周期性，全芯片匹配库必须增收非周期 clips。电源轨往往是最宽、最敏感的 CD，刻蚀负载与它的开口率绑定。</p>',14)),(e(),s(d,null,{default:i(()=>[h(r,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20N%5B%22%E8%BD%A8%E6%95%B0%20N%22%5D%20--%3E%20PITCH%5B%22%E9%87%91%E5%B1%9E%E8%8A%82%E8%B7%9D%22%5D%0A%20%20N%20--%3E%20T2T%5B%22tip%20%2F%20via%20%E5%AF%86%E5%BA%A6%22%5D%0A%20%20PITCH%20--%3E%20PRINT%5B%22%E5%8F%AF%E5%8D%B0%E6%80%A7%20%2F%20%E5%88%86%E8%A7%A3%22%5D%0A%20%20T2T%20--%3E%20PRINT%0A%20%20PRINT%20--%3E%20LIB%5B%22%E5%BA%93%20freeze%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>轨数下降时，图中 tip/via 密度先于金属节距成为可印瓶颈。库 freeze 要把这条路径写进保持集，而不是只交节距表。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不把某代工厂未公开的轨高表当规范。不重写 FinFET/GAA 静电学。轨高选择含电学与时序，本课只交付图形化可行集。</p><p>后课默认：库轨高是已冻结的光刻约束。下一课看埋入电源、接触上栅一类助推器如何在不无限减轨的前提下再挤密度。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>轨道高度把金属节距与单元纵向通道收成整数，是 DTCO 的图形化旋钮。</li><li>少轨提高 tip/via 风险；半轨破坏周期与着色。</li><li>库必须进 OPC 保持集。</li><li>出处：imec DTCO 对 track height 的公开论述；标准单元与可印网格通称。</li></ul>',6))])}const C=l(c,[["render",T]]);export{u as __pageData,C as default};
